// reproducible.js
// This script uses ESLint’s Linter API to dump the code-path graph for `(null && console.log("b")) ?? console.log("c")`.
// You should see that there is no edge from the segment after `a` straight into the `c` evaluation.

const { Linter } = require("eslint");
const linter = new Linter();

linter.defineRule("dump-code-path", {
  meta: { type: "problem" },
  create(context) {
    // Collect all segments and edges
    const nodes = [];
    const edges = [];
    let seenSegments = new Set();

    return {
      onCodePathStart(codePath) {
        // record the initial segment
        const id = codePath.initialSegment.id;
        nodes.push(`\"${id}\" [shape=circle,style=filled,fillcolor=black]`);
        seenSegments.add(id);
      },
      onCodePathSegmentStart(segment) {
        const id = segment.id;
        if (!seenSegments.has(id)) {
          // draw the segment box with node label
          nodes.push(`\"${id}\" [label=\"${id}\"]`);
          seenSegments.add(id);
        }
        // connect each predecessor
        for (const prev of segment.prevSegments) {
          edges.push(`\"${prev.id}\" -> \"${segment.id}\"`);
        }
      },
      onCodePathSegmentLoop(fromSegment, toSegment) {
        edges.push(`\"${fromSegment.id}\" -> \"${toSegment.id}\" [style=dashed,label=\"loop\"]`);
      },
      onCodePathEnd(codePath) {
        // record final segments
        for (const seg of codePath.finalSegments) {
          const id = seg.id;
          nodes.push(`\"${id}\" [shape=doublecircle,style=filled,fillcolor=black]`);
        }
        // print dot
        console.log("digraph codePath { ");
        for (const n of nodes) {
          console.log("  " + n);
        }
        for (const e of edges) {
          console.log("  " + e);
        }
        console.log("}");
      }
    };
  }
});

const code = `(null && console.log("b")) ?? console.log("c");`;
const config = { parserOptions: { ecmaVersion: 2020 } };

// Run ESLint with our custom rule enabled
linter.verify(code, {
  ...config,
  rules: { "dump-code-path": "error" }
});
